-- Status transitions and audit (Oracle 19c PL/SQL)
CREATE OR REPLACE PACKAGE ORDER_PKG AS
  PROCEDURE CHANGE_STATUS(p_order_id IN NUMBER, p_status IN VARCHAR2, p_user IN VARCHAR2, p_result OUT VARCHAR2);
END ORDER_PKG;
/

CREATE OR REPLACE PACKAGE BODY ORDER_PKG AS
  PROCEDURE CHANGE_STATUS(p_order_id IN NUMBER, p_status IN VARCHAR2, p_user IN VARCHAR2, p_result OUT VARCHAR2) IS
    v_old ORDERS.STATUS%TYPE;
  BEGIN
    SELECT STATUS INTO v_old FROM ORDERS WHERE ORDER_ID = p_order_id FOR UPDATE;
    IF v_old = 'SHIPPED' OR (v_old = 'CANCELLED' AND p_status <> 'CANCELLED') THEN
      p_result := 'INVALID_TRANSITION';
      RETURN;
    END IF;
    UPDATE ORDERS SET STATUS = p_status WHERE ORDER_ID = p_order_id;
    INSERT INTO ORDER_AUDIT (ORDER_ID, OLD_STATUS, NEW_STATUS, CHANGED_BY)
      VALUES (p_order_id, v_old, p_status, p_user);
    p_result := 'OK';
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      p_result := 'NOT_FOUND';
  END CHANGE_STATUS;
END ORDER_PKG;
/

CREATE OR REPLACE TRIGGER ORDERS_BI
  BEFORE INSERT ON ORDERS FOR EACH ROW
BEGIN
  IF :NEW.CREATED_AT IS NULL THEN
    :NEW.CREATED_AT := SYSDATE;
  END IF;
END;
/
